begin;
-- File replacement follows the same approved grace as late zero/unrelated referrals.
create or replace function public.add_attachment(p_submission uuid,p_id uuid,p_mime text,p_bytes integer,p_hash text) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.submissions;v integer;deadline timestamptz;begin select * into s from public.submissions where id=p_submission for update;if not found or s.student_id<>auth.uid() or not public.has_role('student',(select department_id from public.events where id=s.event_id)) or s.positive_locked or s.state not in ('draft','revision_requested','zero','wrong_course') then raise exception 'upload forbidden';end if;deadline=s.deadline_snapshot;if s.state='revision_requested' then if s.policy_snapshot->>'revision_hours' is null then raise exception 'revision policy pending';end if;select greatest(deadline,max(a.created_at)+make_interval(hours=>(s.policy_snapshot->>'revision_hours')::int)) into deadline from public.assessments a join public.referrals r on r.id=a.referral_id where r.submission_id=s.id and a.outcome='revision';elsif s.state in ('zero','wrong_course') then if s.policy_snapshot->>'referral_hours' is null then raise exception 'referral policy pending';end if;select greatest(deadline,max(a.created_at)+make_interval(hours=>(s.policy_snapshot->>'referral_hours')::int)) into deadline from public.assessments a join public.referrals r on r.id=a.referral_id where r.submission_id=s.id;end if;if now()>deadline then raise exception 'deadline closed';end if;if exists(select 1 from public.attachments where id=p_id and submission_id=s.id and sha256=p_hash and safety<>'rejected') then return p_id;end if;select coalesce(max(version),0)+1 into v from public.attachments where submission_id=s.id;insert into public.attachments(id,submission_id,version,object_path,mime,bytes,sha256) values(p_id,s.id,v,auth.uid()::text||'/'||s.id::text||'/'||p_id::text,p_mime,p_bytes,p_hash);return p_id;end; $$;
commit;
